@namespace sv_e88279d5f69d45b4b296c1c14f29823a.Components.Pages.Settings
@using sv_e88279d5f69d45b4b296c1c14f29823a.Services
@inject ISettingsService SettingsService

<div class="profile-section">
    @if (isLoading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="avatar-area">
            <div class="avatar-preview">
                @if (!string.IsNullOrEmpty(avatarUrl))
                {
                    <img src="@avatarUrl" alt="Avatar" />
                }
                else
                {
                    <div class="avatar-placeholder">👤</div>
                }
            </div>
            <span class="avatar-url">@avatarUrl</span>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="displayName" @bind:event="oninput" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="email" @bind:event="oninput" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="bio" @bind:event="oninput" rows="4"></textarea>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">✓ Profile saved successfully!</div>
        }
    }
</div>

@code {
    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string avatarUrl = "";

    private UserProfile? savedProfile;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    protected override async Task OnInitializedAsync()
    {
        savedProfile = await SettingsService.GetProfileAsync();
        LoadFromProfile(savedProfile);
        isLoading = false;
    }

    private void LoadFromProfile(UserProfile profile)
    {
        displayName = profile.DisplayName;
        email = profile.Email;
        bio = profile.Bio;
        avatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        var profile = new UserProfile(displayName, email, avatarUrl, bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        isSaving = false;
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            LoadFromProfile(savedProfile);
        }
    }
}

.profile-section {
    max-width: 600px;
}

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f5f5f5;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2rem;
}

.avatar-url {
    font-size: 0.85rem;
    color: #666;
    word-break: break-all;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.35rem;
    color: #333;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    background: #1565c0;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
}

.btn-primary:hover {
    background: #0d47a1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background: transparent;
    color: #555;
    border: 1px solid #ccc;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 500;
}

.btn-secondary:hover {
    background: #f5f5f5;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-weight: 500;
    animation: fadeIn 0.2s ease;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #c8e6c9;
}

.loading {
    color: #666;
    font-style: italic;
}

@@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

