@namespace sv_e88279d5f69d45b4b296c1c14f29823a.Components.Pages.Settings
@using sv_e88279d5f69d45b4b296c1c14f29823a.Services
@inject ISettingsService SettingsService

<div class="notifications-section">
    @if (isLoading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <h3>Notification Channels</h3>

        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="emailNotifications" />
                <span class="toggle-label">Email Notifications</span>
                <span class="toggle-description">Receive notifications via email</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="pushNotifications" />
                <span class="toggle-label">Push Notifications</span>
                <span class="toggle-description">Receive push notifications on your devices</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="weeklyDigest" />
                <span class="toggle-label">Weekly Digest</span>
                <span class="toggle-description">Get a weekly summary of activity</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in allChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">✓ Preferences saved successfully!</div>
        }
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    // Example channels — in production these would come from a service
    private static readonly string[] allChannels = { "General", "Announcements", "Marketing", "Engineering", "Support", "Random" };

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        isSaving = false;
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

