toolArgs.file_text:
.security-section {
    max-width: 700px;
}

.panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.85rem 1rem;
    background: #fafafa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
    color: #333;
    text-align: left;
}

.panel-header:hover {
    background: #f0f0f0;
}

.chevron {
    transition: transform 0.2s;
    font-size: 0.75rem;
}

.chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.35rem;
    color: #333;
}

.form-group input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.error-message {
    color: #c62828;
    background: #ffebee;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    margin-bottom: 0.75rem;
    font-size: 0.9rem;
}

.tfa-section {
    margin-bottom: 1.5rem;
}

.tfa-section h3 {
    margin-bottom: 0.75rem;
    color: #333;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.toggle-label {
    font-weight: 500;
}

.status-badge {
    padding: 0.25rem 0.6rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 600;
}

.status-badge.enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-badge.disabled {
    background: #fbe9e7;
    color: #bf360c;
}

.last-change {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #666;
}

.sessions-section h3 {
    margin-bottom: 0.75rem;
    color: #333;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #eee;
}

.sessions-table th {
    background: #fafafa;
    font-weight: 600;
    color: #555;
}

.current-badge {
    font-size: 0.8rem;
    color: #1565c0;
    font-weight: 600;
}

.btn-primary {
    background: #1565c0;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-danger-sm {
    background: transparent;
    color: #c62828;
    border: 1px solid #c62828;
    padding: 0.3rem 0.6rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-danger-sm:hover {
    background: #ffebee;
}

.btn-danger {
    background: #c62828;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
}

.btn-danger:hover {
    background: #b71c1c;
}

.btn-secondary {
    background: transparent;
    color: #555;
    border: 1px solid #ccc;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
}

.dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    border-radius: 12px;
    padding: 1.5rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.dialog h4 {
    margin: 0 0 0.75rem;
    color: #333;
}

.dialog p {
    color: #555;
    margin-bottom: 1.25rem;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

.toast {
    margin-bottom: 0.75rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-weight: 500;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #c8e6c9;
}

.loading {
    color: #666;
    font-style: italic;
}

