@namespace sv_e88279d5f69d45b4b296c1c14f29823a.Components.Pages.Settings
@using sv_e88279d5f69d45b4b296c1c14f29823a.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (isLoading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <!-- Theme -->
        <div class="setting-group">
            <h3>Theme</h3>
            <div class="radio-group">
                @foreach (var option in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@option"
                               checked="@(theme == option)"
                               @onchange="() => theme = option" />
                        <span>@option</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size -->
        <div class="setting-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                @foreach (var option in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@option"
                               checked="@(fontSize == option)"
                               @onchange="() => fontSize = option" />
                        <span>@option</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language -->
        <div class="setting-group">
            <h3>Language</h3>
            <select @bind="language">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
                <option value="zh">中文</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="setting-group">
            <h3>Compact Mode</h3>
            <label class="toggle-item">
                <input type="checkbox" @bind="compactMode" />
                <span>Enable compact mode for denser information display</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h4>Preview</h4>
            <div class="preview-content">
                <p class="preview-heading">Sample Heading</p>
                <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">✓ Appearance settings saved!</div>
        }
    }
</div>

@code {
    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        theme = settings.Theme;
        fontSize = settings.FontSize;
        language = settings.Language;
        compactMode = settings.CompactMode;
        isLoading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{theme.ToLowerInvariant()} font-{fontSize.ToLowerInvariant()}";
        if (compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        isSaving = false;
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.appearance-section {
    max-width: 600px;
}

.setting-group {
    margin-bottom: 1.5rem;
}

.setting-group h3 {
    margin-bottom: 0.6rem;
    color: #333;
    font-size: 1rem;
}

.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    padding: 0.4rem 0.75rem;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    transition: border-color 0.15s, background 0.15s;
}

.radio-item:hover {
    background: #f5f5f5;
}

.radio-item:has(input:checked) {
    border-color: #1565c0;
    background: #e3f2fd;
}

select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    min-width: 200px;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
}

/* Live Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 10px;
    padding: 1.25rem;
    margin-bottom: 1.5rem;
    transition: all 0.3s;
}

.preview-area h4 {
    margin: 0 0 0.75rem;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #888;
}

.preview-content {
    padding: 1rem;
    border-radius: 8px;
    border: 1px solid #eee;
}

.preview-heading {
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
    color: #555;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 6px;
    border: none;
    font-weight: 600;
    cursor: pointer;
}

/* Theme variants */
.preview-area.theme-light {
    background: #ffffff;
}

.preview-area.theme-light .preview-content {
    background: #f9f9f9;
    color: #222;
}

.preview-area.theme-light .preview-button {
    background: #1565c0;
    color: white;
}

.preview-area.theme-dark {
    background: #1e1e1e;
    border-color: #333;
}

.preview-area.theme-dark h4 {
    color: #aaa;
}

.preview-area.theme-dark .preview-content {
    background: #2d2d2d;
    border-color: #444;
    color: #eee;
}

.preview-area.theme-dark .preview-heading {
    color: #fff;
}

.preview-area.theme-dark .preview-text {
    color: #ccc;
}

.preview-area.theme-dark .preview-button {
    background: #42a5f5;
    color: #111;
}

.preview-area.theme-system {
    background: #f5f5f5;
}

.preview-area.theme-system .preview-content {
    background: #fff;
}

.preview-area.theme-system .preview-button {
    background: #1565c0;
    color: white;
}

/* Font size variants */
.preview-area.font-small .preview-content {
    font-size: 0.85rem;
}

.preview-area.font-medium .preview-content {
    font-size: 1rem;
}

.preview-area.font-large .preview-content {
    font-size: 1.15rem;
}

/* Compact variant */
.preview-area.compact .preview-content {
    padding: 0.5rem;
    line-height: 1.3;
}

.preview-area.compact .preview-heading {
    margin-bottom: 0.25rem;
}

.preview-area.compact .preview-text {
    margin-bottom: 0.4rem;
}

/* Buttons */
.button-group {
    margin-top: 1.5rem;
}

.btn-primary {
    background: #1565c0;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
}

.btn-primary:hover {
    background: #0d47a1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-weight: 500;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #c8e6c9;
}

.loading {
    color: #666;
    font-style: italic;
}

