@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (isLoading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <!-- Theme -->
        <div class="setting-group">
            <h3>Theme</h3>
            <div class="radio-group">
                @foreach (var option in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@option"
                               checked="@(theme == option)"
                               @onchange="() => theme = option" />
                        <span>@option</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size -->
        <div class="setting-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                @foreach (var option in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@option"
                               checked="@(fontSize == option)"
                               @onchange="() => fontSize = option" />
                        <span>@option</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language -->
        <div class="setting-group">
            <h3>Language</h3>
            <select @bind="language">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
                <option value="zh">中文</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="setting-group">
            <h3>Compact Mode</h3>
            <label class="toggle-item">
                <input type="checkbox" @bind="compactMode" />
                <span>Enable compact mode for denser information display</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h4>Preview</h4>
            <div class="preview-content">
                <p class="preview-heading">Sample Heading</p>
                <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">✓ Appearance settings saved!</div>
        }
    }
</div>

@code {
    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    protected override async Task OnInitializedAsync()
