arguments.file_text:
@page "/settings"
@using sv_e88279d5f69d45b4b296c1c14f29823a.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        <h2>@activeSection</h2>

        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        activeSection = section;
    }
}

.settings-page {
    display: flex;
    min-height: calc(100vh - 4rem);
    background: #fff;
    border-radius: 12px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.06);
    overflow: hidden;
}

.settings-content {
    flex: 1;
    padding: 2rem;
}

.settings-content h2 {
    margin: 0 0 1.5rem;
    color: #222;
    font-size: 1.5rem;
    border-bottom: 1px solid #eee;
    padding-bottom: 0.75rem;
}

